from content_core import *
def build():
 out=[]
 def a(topic,sub,stem,ans,chk,sol,wrong,art=''):
  n=len(out)+1;out.append(item(8,'november-mock',n,topic,sub,min(5,(n+4)//5),stem,ans,chk,sol,wrong,art,True))
 a(AR,'Visual fractions','A stage crew paints five equal panels. Two panels are entirely blue, a third is half blue, and the other two contain no blue. What fraction of the whole wall is blue?',F(1,2),F(sum([2,2,1,0,0]),10),'Count half-panels: five of the ten half-panels are blue, so the fraction is 5/10 = 1/2.',[F(2,5),F(3,5),F(1,5),F(3,10)])
 a(AR,'Elapsed time','A rehearsal starts at 9:48 a.m., pauses for 7 minutes, and ends at 10:21 a.m. How many minutes were spent rehearsing?',26,(10*60+21)-(9*60+48)-7,'The clock advances 12 minutes to 10:00 and 21 more to 10:21. Remove 7 from 33 to get 26.',[19,33,40,27])
 a(SEQ,'Patterns','A paper chain repeats red, red, gold, green, gold in that order. What is the position of the ninth gold link, counting the first link as position 1?',23,[i for i in range(1,40) if (i-1)%5 in (2,4)][8],'Four complete blocks have eight gold links and use 20 positions. The next gold is third in its block, at 23.',[18,20,22,25])
 a(PRO,'Averages','Four teams together collected 58 batteries. The first three collected 9, 14 and 16. How many more than the first team did the fourth collect?',10,58-2*9-14-16,'The fourth collected 58−(9+14+16)=19. Compared with the first team that is 19−9=10 more.',[9,11,19,20])
 a(GEO,'Rectangular frames','A photo measures 5 cm by 8 cm. A uniform 1 cm border surrounds its outside. What is the area of the border in square centimetres?',30,sum(not(1<=x<=5 and 1<=y<=8) for x in range(7) for y in range(10)),'Adding a border on both sides makes a 7 by 10 rectangle. Subtract the photo: 70−40=30.',[13,26,28,40])
 a(AR,'Sharing','Three jars hold 12, 17 and 25 beads. A move takes one bead from a jar and puts it in another. What is the minimum number of moves to make all three quantities equal?',7,sum(max(0,18-t) for t in (12,17,25)),'There are 54 beads, so each jar needs 18. The last jar has 7 too many. Moving six to the first and one to the second reaches the target in seven moves.',[5,6,8,14])
 a(NT,'Divisibility','The tens and ones digits of a two-digit number add to 11. Reversing them increases the number by 27. What was the original number?',47,next(x for x in range(10,100) if sum(map(int,str(x)))==11 and int(str(x)[::-1])-x==27),'Reversal changes the value by nine times (ones digit − tens digit), so the ones digit is 3 larger. The digits add to 11, giving 4 and 7: the number is 47.',[38,56,65,74])
 a(GEO,'Dissection','A 12 by 8 sheet is folded once so the two short edges coincide. A 2 by 3 rectangular notch is cut through both layers, away from the fold. What area remains after unfolding?',84,12*8-2*(2*3),'The fold creates two layers. Each loses 6 square units, so 96−12=84 remain.',[48,78,90,96])
 a(PRO,'Probability','A bag contains four plain counters and three striped ones. One counter is removed without looking, and then another is drawn. What is the probability that the first is plain and the second striped?',F(2,7),F(sum(x<4<=y for x,y in permutations(range(7),2)),42),'The first event has probability 4/7. After a plain counter leaves, three of the six left are striped. Multiply: (4/7)(3/6)=2/7.',[F(3,7),F(4,7),F(12,49),F(1,2)])
 a(AR,'Speed','A bicycle courier covers the first 3 km in 12 minutes and the next 5 km in 18 minutes. What was the average speed over the whole trip, in km/h?',16,F(8*60,30),'Use total distance and total time, not the unweighted average of segment speeds. Eight kilometres in half an hour is 16 km/h.',[12,15,17,20])
 a(SEQ,'Differences','On day 1 a club earns 3 points. Each following day it earns 2 more points than the previous day. On which day does the cumulative total first exceed 75?',8,next(n for n in range(1,20) if sum(2*t+1 for t in range(1,n+1))>75),'The first n odd numbers starting at 3 sum to n(n+2). Seven days give 63; eight give 80, the first total above 75.',[6,7,9,10])
 a(CNT,'Combinations','A menu offers three soups and four sandwiches. One sandwich is nut-free; exactly two soups are nut-free. How many soup-and-sandwich meals have at least one nut-free item?',9,sum(s<2 or b==0 for s,b in product(range(3),range(4))),'There are 12 meals. Those with neither nut-free item use the one other soup and one of three other sandwiches: three meals. Thus 12−3=9.',[5,6,8,10])
 a(GEO,'Cube surface','Two identical cubes of side 3 cm are glued face to face. How many square centimetres of the resulting solid are exposed?',90,2*(3*3+3*6+3*6),'Two loose cubes have 12 faces. The two joined faces become internal, leaving 10 faces of area 9, for 90.',[54,72,99,108])
 a(NT,'Remainders','A drum taps at times 2, 8, 14, … seconds. A bell rings at 5, 14, 23, … seconds. At what time after 14 seconds do they next sound together?',32,next(t for t in range(15,100) if (t-2)%6==0 and (t-5)%9==0),'Once the sounds coincide, their coincidence repeats after lcm(6,9)=18 seconds. Add 18 to 14 to get 32.',[23,29,36,41])
 a(ALG,'Balances','Two full identical water bottles and one empty bottle weigh 870 g. One full bottle and two empty bottles weigh 540 g. How many grams of water does a full bottle contain?',330,next(x for x in range(871) if any(3*b+2*x==870 and 3*b+x==540 for b in [((540-x)//3)])),'Both weighings contain three empty bottle shells. The first has exactly one additional bottleful of water, so subtract: 870−540=330 g.',[110,210,270,435])
 a(LOG,'Truth statements','Four boxes A, B, C, D hide one token. Their labels say, respectively: “in B or C”, “not in A”, “in D”, and “not in C”. Exactly three labels are true. How many possible hiding places are there?',2,sum(sum([p in "BC",p!="A",p=="D",p!="C"])==3 for p in 'ABCD'),'If the token is in A, B, C or D, the numbers of true labels are respectively 1, 3, 2 and 3. B and D work, giving two possibilities.',[0,1,3,4])
 a(PRO,'Weighted averages','A class scored an average of 14 on a quiz. When one score of 26 is removed, the remaining class average is 13. How many people were originally in the class?',13,next(n for n in range(2,100) if 14*n-26==13*(n-1)),'For n students, 14n−26=13(n−1). Expanding and simplifying gives n=13.',[11,12,14,15])
 a(CNT,'Counting rectangles','On a 3 by 3 board of unit cells, how many axis-parallel squares of any size contain the central cell?',6,sum(a<=1<a+s and b<=1<b+s for s in range(1,4) for a in range(4-s) for b in range(4-s)),'There is one single-cell square, four different 2 by 2 squares, and one 3 by 3 square containing the centre. Their total is 6.',[4,5,8,9])
 a(AR,'Fractional changes','A jug is one-third full. After 8 cups are poured in, it is three-quarters full. How many cups would fill the jug from empty?',F(96,5),8/(F(3,4)-F(1,3)),'The added fraction is 3/4−1/3=5/12. If 5/12 of capacity is 8 cups, the full capacity is 8×12/5=96/5 cups.',[16,18,20,24])
 a(NT,'Factors','Among the positive integers less than 50, how many have exactly three positive divisors?',4,sum(sum(n%d==0 for d in range(1,n+1))==3 for n in range(1,50)),'A number with three divisors must be a prime square: its divisors are 1,p,p². The eligible primes are 2,3,5,7, giving four squares.',[3,5,6,7])
 a(GEO,'Surface layers','A solid 4 by 5 by 6 block made of unit cubes is painted on every outside face. How many unit cubes have paint on exactly two faces?',36,sum(sum(t in (0,d-1) for t,d in zip(p,[4,5,6]))==2 for p in product(range(4),range(5),range(6))),'These cubes lie on edges, excluding corners. Four edges in each direction contribute 4[(4−2)+(5−2)+(6−2)]=36.',[24,32,44,48])
 a(CNT,'Restricted arrangements','Five bins stand in a row. Three indistinguishable red balls and two indistinguishable blue balls are placed one per bin. How many arrangements have the red balls in exactly two consecutive groups?',6,sum(1 for red in combinations(range(5),3) if sum(x-1 not in red for x in red)==2),'The ordered red group lengths are (1,2) or (2,1). The two blue balls must separate the groups; placing the extra blue before, between, or after gives three choices per order. Total 6.',[3,4,5,8])
 a(ALG,'Reciprocal rates','A rooftop tank fills in 12 minutes with tap A and in 18 minutes with tap B. They run together for 4 minutes, then B shuts off. How many more minutes must A run?',F(16,3),(1-4*(F(1,12)+F(1,18)))/F(1,12),'Together the taps fill 5/36 per minute, hence 5/9 in four minutes. The remaining 4/9 takes (4/9)×12=16/3 minutes with A.',[4,F(20,3),6,8])
 a(SEQ,'Invariants','A row starts as 14 white and 9 black counters. A move removes two counters: if their colours match, return a white counter; if they differ, return a black counter. After 22 moves how many black counters remain?',1,9%2,'A move changes the black count by zero or two, so its parity stays odd. Each move reduces the total by one; 23 counters become one. It must be black.',[0,2,3,9])
 a(LOG,'Extremal arrangements','Seven distinct whole numbers are chosen from 1 through 12. What is the smallest possible number of pairs of chosen numbers that differ by 1?',1,min(sum(t+1 in s for t in s) for s in combinations(range(1,13),7)),'Five unchosen numbers can split chosen numbers into at most six runs. With seven chosen, at least one adjacent pair occurs. Choose 1,2,4,6,8,10,12 to attain exactly one.',[0,2,3,5])
 return out
